def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for r in range(h):
        # The top and left margins form a fixed 1/4 border.
        for c in range(w):
            if grid[r][c] == 0 and (r < 3 or c < 3):
                if r < 2 or c < 2:
                    out[r][c] = 1
                else:
                    out[r][c] = 4

        # The interior repeats horizontally. Infer its period from the
        # undamaged portion of this row, then fill missing cells by phase.
        known = [c for c in range(6, w) if grid[r][c] != 0]
        if not known:
            continue

        candidates = []
        for p in range(2, 11):
            pairs = [(c, c + p) for c in known if c + p < w and grid[r][c + p] != 0]
            if len(pairs) >= 3:
                errors = sum(grid[r][a] != grid[r][b] for a, b in pairs)
                candidates.append((errors / len(pairs), p))

        period = min(candidates)[1] if candidates else 5

        phases = {}
        for c in range(6, w):
            if grid[r][c] != 0:
                phases.setdefault(c % period, []).append(grid[r][c])

        for c in range(3, w):
            if grid[r][c] == 0 and c % period in phases:
                values = phases[c % period]
                out[r][c] = max(set(values), key=values.count)

    return out
